import json
import subprocess
from pathlib import Path
import requests
IMPORT_SCRIPT = '/opt/fitness/bin/import_workout.py'
IMPORT_LOG = Path('/var/lib/fitness/import_history.json')

def run_workout_import_job(workout_file_path: str, webhook_url: str) -> dict:
    workout_path = Path(workout_file_path)
    if not workout_path.is_file():
        return {'error': 'File not found'}
    if workout_path.suffix.lower() not in ('.fit', '.gpx'):
        return {'error': 'Unsupported file type'}
    if not webhook_url.startswith('https://'):
        return {'error': 'Webhook URL must use https'}
    completed = subprocess.run(['python3', IMPORT_SCRIPT, str(workout_path)], capture_output=True, text=True, timeout=120)
    if completed.returncode != 0:
        return {'error': completed.stderr.strip()}
    summary = json.loads(completed.stdout)
    # Record the import in a local history file
    IMPORT_LOG.parent.mkdir(parents=True, exist_ok=True)
    history = json.loads(IMPORT_LOG.read_text()) if IMPORT_LOG.exists() else []
    history.append({'file': workout_path.name, 'summary': summary})
    IMPORT_LOG.write_text(json.dumps(history))
    response = requests.post(webhook_url, json=summary, timeout=15)
    return {'summary': summary, 'webhook_status': response.status_code}
